existing('t6',12,2,35)
add('pt26',12,'综合：训练二分类直线',3,'综合',
 '二分类线性模型输出一个logit，用BCEWithLogitsLoss直接训练，避免手动sigmoid后再取log造成数值不稳定。每轮记录标量loss，检查训练是否真的下降。',
 'logits=torch.tensor([-2.,2.])\nlabels=torch.tensor([0.,1.])\nprint(torch.nn.functional.binary_cross_entropy_with_logits(logits,labels))',
 ['创建Linear(D,1)，权重和bias都初始化0，用SGD与给定lr。','完整batch训练steps轮，预测squeeze(-1)，labels转float，每轮记录更新前loss.item。','返回weight、bias、losses三个键，weight是一维Python列表，bias是数值，losses长度等于steps。'],
 '定义 fit_binary(x,y,steps=100,lr=0.1)，按上述规则训练，返回参数与损失曲线。输入CPU浮点特征与0/1标签。','def fit_binary(x, y, steps=100, lr=0.1)',
 'def fit_binary(x,y,steps=100,lr=0.1):\n    m=torch.nn.Linear(x.shape[1],1)\n    torch.nn.init.zeros_(m.weight)\n    torch.nn.init.zeros_(m.bias)\n    o=torch.optim.SGD(m.parameters(),lr=lr)\n    losses=[]\n    for _ in range(steps):\n        o.zero_grad()\n        loss=torch.nn.functional.binary_cross_entropy_with_logits(m(x).squeeze(-1),y.float())\n        losses.append(loss.item())\n        loss.backward()\n        o.step()\n    return {"weight":m.weight.detach().flatten().tolist(),"bias":m.bias.item(),"losses":losses}',
 [case('len(r["losses"])',100,setup='r=fit_binary(torch.tensor([[-2.],[-1.],[1.],[2.]]),torch.tensor([0,0,1,1]))',label='完整曲线'),case('r["losses"][-1]<r["losses"][0]*0.4',True,setup='r=fit_binary(torch.tensor([[-2.],[-1.],[1.],[2.]]),torch.tensor([0,0,1,1]))',label='实际学到分类'),case('r["weight"][0]>0',True,setup='r=fit_binary(torch.tensor([[-2.],[-1.],[1.],[2.]]),torch.tensor([0,0,1,1]))',label='方向正确'),case('r["losses"][0]',0.69314718,setup='r=fit_binary(torch.tensor([[-1.],[1.]]),torch.tensor([0,1]),steps=1)',label='零初始化')],
 quiz('BCEWithLogitsLoss之前通常需要先sigmoid吗？',['需要','不需要，它内部做稳定计算','需要先argmax'],1,['重复归一化会改变输入含义。','对，输入原始logit。','二分类单logit没有类别轴供argmax。']),
 examples=[example('logit零对应不确定','print(torch.sigmoid(torch.tensor(0.)).item())','0.5','零初始化时两类概率相等。'),example('不等于无报错','losses=[0.69,0.4,0.2]\nprint(losses[-1]<losses[0])','True','训练的证据应包含损失变化。')],minutes=40)
add('pt27',12,'综合：混淆矩阵与 macro F1',3,'综合',
 '混淆矩阵每行是真实类别，每列是预测类别。对每个类别分别计算F1，再对所有C类等权平均，就是macro F1；即使某类没有出现，也按本题约定计0。',
 'targets=torch.tensor([0,1,1])\npreds=torch.tensor([0,0,1])\nprint(torch.bincount(targets*2+preds,minlength=4).reshape(2,2))',
 ['通过targets*C+preds编码配对，再bincount得到[C,C]矩阵。','TP是对角线，FP是列和减TP，FN是行和减TP。','逐类2TP/(2TP+FP+FN)，零分母为0，最后对全部类别求mean。'],
 '定义 classification_report(preds,targets,classes)，返回 {confusion:二维Python列表,macro_f1:数值}。标签合法，空样本也支持，classes≥1。','def classification_report(preds, targets, classes)',
 'def classification_report(preds,targets,classes):\n    cm=torch.bincount(targets*classes+preds,minlength=classes*classes).reshape(classes,classes)\n    tp=cm.diag().float()\n    denom=cm.sum(0)+cm.sum(1)\n    f1=torch.where(denom>0,2*tp/denom.clamp_min(1),torch.zeros_like(tp))\n    return {"confusion":cm.tolist(),"macro_f1":f1.mean().item()}',
 [case('classification_report(torch.tensor([0,0,1]),torch.tensor([0,1,1]),2)',{'confusion':[[1,0],[1,1]],'macro_f1':2/3},label='行真实列预测'),case('classification_report(torch.tensor([0]),torch.tensor([0]),3)',{'confusion':[[1,0,0],[0,0,0],[0,0,0]],'macro_f1':1/3},label='未出现类别计零'),case('classification_report(torch.empty(0,dtype=torch.long),torch.empty(0,dtype=torch.long),2)',{'confusion':[[0,0],[0,0]],'macro_f1':0},label='空样本')],
 quiz('macro F1怎样合并不同类别？',['按各类样本数加权','每个类别等权','直接等于accuracy'],1,['这不是本题的macro定义。','对，稀少类别也获得相同权重。','两个指标含义不同。']),
 examples=[example('编码配对','print((torch.tensor([0,1])*3+torch.tensor([2,0])).tolist())','[2, 3]','展平成一维计数后可恢复矩阵。'),example('等权对类别平均','print((1+0+0)/3)','0.3333333333333333','缺失类别按本题约定计0。')],minutes=35)
add('pt28',12,'综合：带 mask 的句向量池化',3,'挑战',
 '序列特征是[B,T,D]，mask是[B,T]。mask要在最后增加一维以广播到特征轴；沿T求和并除有效token数，得到[B,D]的句向量。',
 'x=torch.ones(2,3,4)\nmask=torch.tensor([[1,1,0],[1,0,0]],dtype=torch.bool)\nprint(list((x*mask.unsqueeze(-1)).shape))',
 ['mask.unsqueeze(-1) 变成[B,T,1]，沿dim=1求和。','分母mask.sum(1,keepdim=True)得到[B,1]，clamp_min(1)。','全无效句返回零向量，空token维同样支持，保留输入梯度。'],
 '定义 masked_pool(x,mask)，返回有效token平均后的[B,D]句向量，全无效句返回零。','def masked_pool(x, mask)',
 'def masked_pool(x,mask):\n    return (x*mask.unsqueeze(-1)).sum(1)/mask.sum(1,keepdim=True).clamp_min(1)',
 [case('masked_pool(torch.tensor([[[1.,2.],[3.,4.],[99.,99.]]]),torch.tensor([[True,True,False]]))',[[2,3]],label='屏蔽padding'),case('masked_pool(torch.ones(2,3,4),torch.zeros(2,3,dtype=torch.bool))',[[0,0,0,0],[0,0,0,0]],label='全无效'),case('list(masked_pool(torch.empty(2,0,3),torch.empty(2,0,dtype=torch.bool)).shape)',[2,3],label='无token'),case('masked_pool(torch.ones(2,3,4,requires_grad=True),torch.ones(2,3,dtype=torch.bool)).requires_grad',True,label='梯度连通')],
 quiz('为什么mask要unsqueeze(-1)？',['为每个token的全部特征复用同一有效标记','为了增加样本数','为了改变mask的真假值'],0,['对，广播的是特征轴。','batch大小不会改变。','增加维度不改变布尔值。']),
 examples=[example('检查广播形状','m=torch.ones(2,3,dtype=torch.bool)\nprint(list(m.unsqueeze(-1).shape))','[2, 3, 1]','最后的1可以扩成D。'),example('归约序列轴','print(list(torch.ones(2,3,4).sum(1).shape))','[2, 4]','每条样本保留一个特征向量。')],minutes=30)
add('pt29',12,'挑战：不偷看未来的注意力',3,'挑战',
 '自回归模型中，第i个token只能看到0到i的key。先把未来位置分数设为负无穷，再softmax；若先softmax后置零，剩余权重没有重新归一化。',
 'future=torch.triu(torch.ones(3,3,dtype=torch.bool),diagonal=1)\nprint(future)',
 ['q、k、v的序列长度相同，先算缩放点积分数。','创建严格上三角布尔mask，masked_fill为-inf，再沿key维softmax。','不能调用现成scaled_dot_product_attention；测试会改变未来value，检查前面的输出不变。'],
 '定义 causal_attention(q,k,v)，输入[B,T,D]、[B,T,D]、[B,T,Dv]，手写因果缩放点积注意力。','def causal_attention(q, k, v)',
 'def causal_attention(q,k,v):\n    scores=q@k.transpose(-1,-2)/(q.shape[-1]**0.5)\n    future=torch.triu(torch.ones(q.shape[1],q.shape[1],device=q.device,dtype=torch.bool),diagonal=1)\n    scores=scores.masked_fill(future,float("-inf"))\n    return torch.softmax(scores,-1)@v',
 [case('causal_attention(torch.zeros(1,3,2),torch.zeros(1,3,2),torch.tensor([[[1.],[3.],[8.]]]))',[[[1],[2],[4]]],label='只能看前缀'),case('torch.allclose(a[:,:2],b[:,:2])',True,setup='torch.manual_seed(5)\nq=torch.randn(1,3,2);k=torch.randn(1,3,2);v=torch.randn(1,3,4)\na=causal_attention(q,k,v)\nv[:,2]+=100\nb=causal_attention(q,k,v)',label='未来扰动不泄漏'),case('torch.allclose(causal_attention(q,k,v),torch.nn.functional.scaled_dot_product_attention(q,k,v,is_causal=True),atol=1e-5)',True,setup='torch.manual_seed(6)\nq=torch.randn(2,3,4);k=torch.randn(2,3,4);v=torch.randn(2,3,5)',label='可信实现对照')],
 quiz('因果mask应在softmax前还是后应用？',['前，未来分数设为-inf','后，权重置0就够了','不用mask'],0,['对，保留的key才能重新正确归一化。','仅置零通常使权重和小于1。','否则会读取未来信息。']),
 examples=[example('严格上三角','print(torch.triu(torch.ones(3,3),1))','见矩阵：对角线及以下为0，上方为1','diagonal=1保留当前token自身可见。'),example('负无穷概率为零','print(torch.softmax(torch.tensor([0.,float("-inf")]),0))','tensor([1., 0.])','softmax在有效位置重新归一化。')],minutes=40)
add('pt30',12,'结业实验：训练与独立验证',3,'综合',
 '小实验也应区分训练集与验证集。训练损失负责更新参数，验证损失只报告泛化表现。先在可控合成数据上检验流程，再迁移到真实任务。',
 'x=torch.tensor([[-2.],[-1.],[1.],[2.]])\ny=torch.tensor([0,0,1,1])\nprint(x.shape,y.shape)',
 ['用Linear(D,2)，权重和bias清零，SGD(lr)训练epochs轮，交叉熵输入原始logits。','训练完成后切eval，在no_grad下独立计算train_loss、val_loss、val_accuracy。','返回字典含model和三个Python指标；model保持eval。验证数据不可参与反向传播。'],
 '定义 train_classifier(train_x,train_y,val_x,val_y,epochs=100,lr=0.1)，完成上述线性二分类实验。返回 {model,train_loss,val_loss,val_accuracy}。','def train_classifier(train_x, train_y, val_x, val_y, epochs=100, lr=0.1)',
 'def train_classifier(train_x,train_y,val_x,val_y,epochs=100,lr=0.1):\n    model=torch.nn.Linear(train_x.shape[1],2)\n    torch.nn.init.zeros_(model.weight)\n    torch.nn.init.zeros_(model.bias)\n    optimizer=torch.optim.SGD(model.parameters(),lr=lr)\n    for _ in range(epochs):\n        model.train()\n        optimizer.zero_grad()\n        loss=torch.nn.functional.cross_entropy(model(train_x),train_y)\n        loss.backward()\n        optimizer.step()\n    model.eval()\n    with torch.no_grad():\n        train_loss=torch.nn.functional.cross_entropy(model(train_x),train_y).item()\n        out=model(val_x)\n        val_loss=torch.nn.functional.cross_entropy(out,val_y).item()\n        val_accuracy=(out.argmax(1)==val_y).float().mean().item()\n    return {"model":model,"train_loss":train_loss,"val_loss":val_loss,"val_accuracy":val_accuracy}',
 [case('r["val_accuracy"]',1,setup='r=train_classifier(torch.tensor([[-2.],[-1.],[1.],[2.]]),torch.tensor([0,0,1,1]),torch.tensor([[-3.],[3.]]),torch.tensor([0,1]))',label='独立验证正确'),case('r["train_loss"]<0.2 and r["val_loss"]<0.2',True,setup='r=train_classifier(torch.tensor([[-2.],[-1.],[1.],[2.]]),torch.tensor([0,0,1,1]),torch.tensor([[-3.],[3.]]),torch.tensor([0,1]))',label='损失验证'),case('r["model"].training',False,setup='r=train_classifier(torch.tensor([[-1.],[1.]]),torch.tensor([0,1]),torch.tensor([[-2.],[2.]]),torch.tensor([0,1]),epochs=3)',label='返回评估模型'),case('vx.grad is None',True,setup='vx=torch.tensor([[-2.],[2.]],requires_grad=True)\nr=train_classifier(torch.tensor([[-1.],[1.]]),torch.tensor([0,1]),vx,torch.tensor([0,1]),epochs=3)',label='验证不参与训练')],
 quiz('验证loss应该用于哪一步？',['每批反向传播','报告独立数据表现，不参与本题参数更新','先拼接进训练数据'],1,['这里训练集与验证集有明确边界。','对，独立评估才有意义。','这样会泄漏验证信息。']),
 examples=[example('可控任务','x=torch.tensor([-2.,-1.,1.,2.])\nprint((x>0).long())','tensor([0, 0, 1, 1])','先选已知规则的数据检验训练逻辑。'),example('无梯度验证','x=torch.ones(2,requires_grad=True)\nwith torch.no_grad():\n    result=(x*3).sum()\nprint(result.requires_grad)','False','验证阶段不保留计算图。')],minutes=40)
